const chatId = msg.payload.chatId;
flow.set(`state_${chatId}`, null);

return msg;

const chatId = msg.payload.chatId;
const state = flow.get(`state_${chatId}`);

// Допоміжні функції

function writeLog(step, summary) {
    const entry = {
        timestamp: new Date().toISOString(),
        chatId: chatId,
        step: step,
        summary: summary
    };

    node.warn(JSON.stringify(entry));
}

function sendReply(text) {
    msg.payload.type = "message";
    msg.payload.content = text;
    msg.payload.inbound = false;

    return [msg, null]; // Перший вихід — відповідь користувачу.
}

function showError(reason) {
    writeLog("calc:validation_failed", reason);

    return sendReply(
        reason +
        "\nСпробуй ще раз, наприклад: 12 + 7." +
        "\nДля повернення до меню — /menu."
    );
}

// 1. Перевіряємо, чи користувач у калькуляторі.

if (state !== "calculator") {
    writeLog("menu:fallback", "Нерозпізнаний ввід");

    return [null, msg]; // Другий вихід — меню.
}

// 2. Перевіряємо вхідне повідомлення.

const input = msg.payload.content;

writeLog("calc:input_received", "Отримано ввід для калькулятора");

if (typeof input !== "string") {
    return showError("Надішли вираз текстовим повідомленням.");
}

if (input.length > 100) {
    return showError("Повідомлення надто довге. Максимум — 100 символів.");
}

if (input.trim() === "") {
    return showError("Повідомлення порожнє.");
}

// 3. Приводимо символи до єдиного формату.

const expression = input.trim()
    .replace(/,/g, ".")
    .replace(/−/g, "-")
    .replace(/×/g, "*")
    .replace(/÷/g, "/");

// Шукаємо три частини: перше число, операцію, друге число.
// Числа можуть бути від'ємними та мати дробову частину.
const pattern = /^([+-]?\d+(?:\.\d+)?)\s*([+\-*/])\s*([+-]?\d+(?:\.\d+)?)$/;
const parts = expression.match(pattern);

if (!parts) {
    return showError("Введи два числа та операцію між ними.");
}

const firstNumber = Number(parts[1]);
const operation = parts[2];
const secondNumber = Number(parts[3]);

if (!Number.isFinite(firstNumber) || !Number.isFinite(secondNumber)) {
    return showError("Введи коректні скінченні числа.");
}

if (operation === "/" && secondNumber === 0) {
    return showError("Ділити на нуль не можна.");
}

// 4. Виконуємо обчислення.

let result;

switch (operation) {
    case "+":
        result = firstNumber + secondNumber;
        break;

    case "-":
        result = firstNumber - secondNumber;
        break;

    case "*":
        result = firstNumber * secondNumber;
        break;

    case "/":
        result = firstNumber / secondNumber;
        break;
}

if (!Number.isFinite(result)) {
    return showError("Результат надто великий. Введи менші числа.");
}

// 5. Округлюємо до 12 значущих цифр для відображення.
// Наприклад, 0.1 + 0.2 показуємо як 0.3.
const displayedResult = Number(result.toPrecision(12));

writeLog(
    "calc:result",
    `${firstNumber} ${operation} ${secondNumber} = ${displayedResult}`
);

return sendReply(
    `Результат: ${displayedResult}\n\n` +
    "Можеш ввести наступний вираз або надіслати /menu."
);

const chatId = msg.payload.chatId;

flow.set(`state_${chatId}`, null);

msg.telegramPayload = { ...msg.payload };

node.warn(JSON.stringify({
    timestamp: new Date().toISOString(),
    chatId,
    step: "nbu:request_sent",
    summary: "Запит курсу USD та EUR"
}));

delete msg.payload;
return msg;

// Мережеві помилки обробляє нода «Помилка НБУ».
// Звичайний HTTP-статус — це число, наприклад 200 або 404.
if (typeof msg.statusCode !== "number") {
    return null;
}

const currencies = msg.payload;
const chatId = msg.telegramPayload.chatId;

// За замовчуванням готуємо повідомлення про помилку.
let text = "Не вдалося отримати курс. Спробуй пізніше.";
let step = "nbu:error";
let summary = "Некоректна відповідь API. HTTP: " + msg.statusCode;

// Перевіряємо статус і формат відповіді.
if (msg.statusCode === 200 && Array.isArray(currencies)) {
    const usd = currencies.find(currency => currency.cc === "USD");
    const eur = currencies.find(currency => currency.cc === "EUR");

    // Перевіряємо, що обидві валюти мають курс і дату.
    if (
        usd && eur &&
        Number.isFinite(usd.rate) &&
        Number.isFinite(eur.rate) &&
        usd.exchangedate && eur.exchangedate
    ) {
        text = "💱 Офіційний курс НБУ\n\n";
        text += `1 USD = ${usd.rate} грн (${usd.exchangedate})\n`;
        text += `1 EUR = ${eur.rate} грн (${eur.exchangedate})`;

        step = "nbu:success";
        summary = "Отримано курси USD та EUR";
    }
}

text += "\n\nДля повернення до меню — /menu";

// Записуємо результат у лог.
node.warn(JSON.stringify({
    timestamp: new Date().toISOString(),
    chatId: chatId,
    step: step,
    summary: summary
}));

// Відновлюємо дані Telegram і записуємо текст відповіді.
msg.payload = msg.telegramPayload;
msg.payload.type = "message";
msg.payload.content = text;
msg.payload.inbound = false;

return msg;

// Дані чату збережені перед HTTP-запитом.
const telegram = msg.telegramPayload;

node.warn(JSON.stringify({
    timestamp: new Date().toISOString(),
    chatId: telegram.chatId,
    step: "nbu:error",
    summary: msg.error ? msg.error.message : "Помилка HTTP-запиту"
}));

// Користувачу надсилаємо зрозуміле повідомлення.
msg.payload = telegram;
msg.payload.type = "message";
msg.payload.inbound = false;
msg.payload.content =
    "Не вдалося отримати курс. Спробуй пізніше.\n\n" +
    "Для повернення до меню — /menu.";

return msg;

const chatId = msg.payload.chatId;
flow.set(`state_${chatId}`, null);

return msg;

// Обробляємо лише текстові повідомлення.
if (typeof msg.payload.content !== "string") {
    return msg;
}

const text = msg.payload.content
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ");

const chatId = msg.payload.chatId;

// Прості текстові команди.
if (text === "меню" || text === "назад") {
    msg.payload.content = "/menu";
} else if (text === "калькулятор") {
    msg.payload.content = "calc";
} else if (text === "про бота") {
    msg.payload.content = "about";
} else if (
    /^(який курс|курс)( долара| євро| валют| usd| eur)?\??$/.test(text)
) {
    msg.payload.content = "rates";
} else {
    // Наприклад: «скільки буде 5 плюс 7».
    const match = text.match(/^скільки буде\s+(.+?)\??$/);

    if (!match) {
        return msg;
    }

    // Замінюємо назви операцій математичними знаками.
    const expression = match[1]
        .replace(/плюс/g, "+")
        .replace(/мінус/g, "-")
        .replace(/помножити на/g, "*")
        .replace(/поділити на/g, "/");

    flow.set(`state_${chatId}`, "calculator");
    msg.payload.content = expression;
}

return msg;

// Зберігаємо текст відповіді та додаємо кнопку.
msg.payload.type = "inline-buttons";

msg.payload.buttons = [
    {
        type: "postback",
        label: "⬅ Назад",
        value: "/menu"
    }
];

return msg;
